def wheel(id):
 parts=[];vals=[0,10,20,30,40,50,60,65,70,80,90,100]
 for i,n in enumerate(vals):
  theta=math.radians(-90+i*30);a=theta-math.pi/12;b=theta+math.pi/12;r=294
  x1,y1=360+r*math.cos(a),360+r*math.sin(a);x2,y2=360+r*math.cos(b),360+r*math.sin(b)
  fill='#e7d9b8' if i%2==0 else '#c5cbb8'
  if n in (10,65):fill='#e7bd73'
  parts.append(f'<path d="M360 360L{x1} {y1}A{r} {r} 0 0 1 {x2} {y2}Z" fill="{fill}" stroke="#715f48" stroke-width="2"/>')
  x,y=360+231*math.cos(theta),360+231*math.sin(theta)
  parts.append(f'<text x="{x}" y="{y}" fill="#24413d" font-family="Stiles" font-size="35" text-anchor="middle" dominant-baseline="middle" transform="rotate({i*30},{x},{y})">{n}</text>')
 return '<svg viewBox="0 0 720 720" width="720" height="720"><rect x="346" y="622" width="28" height="93" rx="5" fill="#80623f" stroke="#503f2c" stroke-width="3"/><circle cx="360" cy="360" r="312" fill="#685039" stroke="#d1b688" stroke-width="8"/><g id="'+id+'">'+''.join(parts)+'</g><circle cx="360" cy="360" r="39" fill="#caa46a" stroke="#5f4e3a" stroke-width="7"/><circle cx="360" cy="360" r="14" fill="#735b3f"/><path d="M332 26H388L360 89Z" fill="#edcf8d" stroke="#5f4c36" stroke-width="5"/></svg>'
