change('#s1','#s0',C.wheel);tl.fromTo('#wheelOne',{rotation:0,svgOrigin:'360 360'},{rotation:690,svgOrigin:'360 360',duration:4.55,ease:'power2.out'},C.wheel+.14);
change('#s2','#s1',C.globe);tl.fromTo('#s2 .backdrop',{scale:1},{scale:1.025,duration:C.chart-C.globe,ease:'none'},C.globe);
