change('#s4','#s3',C.meaning);gsap.set('#wheelTwo',{rotation:-30,svgOrigin:'360 360'});tl.fromTo('#thought',{autoAlpha:0,y:12},{autoAlpha:1,y:0,duration:.35,ease:'power2.out'},C.focus-.25);tl.to('#meaningRoom',{filter:'blur(10px)',duration:.35},C.focus-.25);tl.to('#meaningWheel',{filter:'blur(6px)',opacity:.58,duration:.35},C.focus-.25);
change('#s5','#s4',C.home);tl.fromTo('#value',{autoAlpha:0,y:18},{autoAlpha:1,y:0,duration:.4,ease:'power2.out'},C.value);tl.to('#value',{autoAlpha:0,duration:.14},C.compare);tl.fromTo('#alternative',{autoAlpha:0,y:12},{autoAlpha:1,y:0,duration:.28,ease:'power2.out'},C.compare+.14);
